-- ============================================================
-- Migration: Exercise catalog and muscle groups
--
-- A read-only catalog of common exercises with the muscles they train,
-- seeded from free-exercise-db (f00c92c, Unlicense). Generated by
-- backend/scripts/generate_exercise_catalog.py; don't edit by hand.
-- The dataset's "shoulders" is split into front, side and rear delts.
--
-- Library entries get their own muscle list, which users pick from the
-- catalog or set by hand. Weekly sets per muscle count a set once for
-- each primary muscle and half for each secondary one.
-- ============================================================

CREATE TABLE exercise_catalog (
    id        BIGSERIAL PRIMARY KEY,
    -- free-exercise-db id, for later migrations that update the catalog
    slug      VARCHAR(100) NOT NULL UNIQUE,
    name      VARCHAR(100) NOT NULL,
    equipment VARCHAR(30),
    category  VARCHAR(30) NOT NULL
);

CREATE TABLE exercise_catalog_muscles (
    catalog_exercise_id BIGINT NOT NULL REFERENCES exercise_catalog(id) ON DELETE CASCADE,
    muscle              VARCHAR(20) NOT NULL,
    role                VARCHAR(10) NOT NULL,
    PRIMARY KEY (catalog_exercise_id, muscle)
);

CREATE TABLE library_exercise_muscles (
    library_exercise_id BIGINT NOT NULL REFERENCES library_exercises(id) ON DELETE CASCADE,
    muscle              VARCHAR(20) NOT NULL,
    role                VARCHAR(10) NOT NULL,
    PRIMARY KEY (library_exercise_id, muscle)
);

ALTER TABLE exercise_catalog_muscles
    ADD CONSTRAINT chk_exercise_catalog_muscles_muscle CHECK (muscle IN ('ABDOMINALS', 'ABDUCTORS', 'ADDUCTORS', 'BICEPS', 'CALVES', 'CHEST', 'FOREARMS', 'FRONT_DELTS', 'GLUTES', 'HAMSTRINGS', 'LATS', 'LOWER_BACK', 'MIDDLE_BACK', 'NECK', 'QUADRICEPS', 'REAR_DELTS', 'SIDE_DELTS', 'TRAPS', 'TRICEPS')),
    ADD CONSTRAINT chk_exercise_catalog_muscles_role CHECK (role IN ('PRIMARY', 'SECONDARY'));

ALTER TABLE library_exercise_muscles
    ADD CONSTRAINT chk_library_exercise_muscles_muscle CHECK (muscle IN ('ABDOMINALS', 'ABDUCTORS', 'ADDUCTORS', 'BICEPS', 'CALVES', 'CHEST', 'FOREARMS', 'FRONT_DELTS', 'GLUTES', 'HAMSTRINGS', 'LATS', 'LOWER_BACK', 'MIDDLE_BACK', 'NECK', 'QUADRICEPS', 'REAR_DELTS', 'SIDE_DELTS', 'TRAPS', 'TRICEPS')),
    ADD CONSTRAINT chk_library_exercise_muscles_role CHECK (role IN ('PRIMARY', 'SECONDARY'));

